mapper.select:
select bm.id, bm.menu_name, bm.menu_code, bm.parent_id, bm.ancestors, bm.menu_type, bm.menu_icon, bm.sort, bm.route_path, bm.active_path, bm.component_path, bm.external_url, bm.is_cache, bm.is_hide_tab, bm.is_hide, bm.is_affix, bm.is_iframe, bm.is_iframe, bm.is_full_screen, bm.is_show_badge, bm.show_text_badge, bm.status, bm.update_time from bedrock_menu bm
inner join bedrock_role_menu brm on brm.menu_id = bm.id
where bm.is_deleted = 0 and bm.status = 1
and brm.role_id in (
#{item}
)
